-- =============================================================================
-- AI-Ready School — CONTENT SEED (for auditing/populating without a terminal)
--
-- HOW TO USE:
--   1) Run supabase/schema.sql first (safe/idempotent — creates the PD tables,
--      policies, and the subject/pillar columns).
--   2) Then run THIS file in Supabase → SQL Editor.
--
-- It REPLACES the sample Cookbook, downloads, and PD courses with the full
-- starter library, so the Owner portal is fully populated to audit.
--
-- NOTE: download FILES (PDFs) are not created here (SQL can't upload files).
-- The download rows will list in the portal; to make the files downloadable,
-- run `npm run seed` (uses the service-role key) or upload via Owner → Resources.
-- =============================================================================

alter table public.recipes   add column if not exists subject text not null default 'Cross-curricular';
alter table public.recipes   add column if not exists pillar text;
alter table public.resources add column if not exists pillar text;

-- Clean slate for the sample library (keeps user accounts/licenses untouched).
delete from public.pd_lessons;
delete from public.pd_courses;
delete from public.resources;
delete from public.recipes;

